use glam::DVec3 as V;use ingetrazo_gui::IngeTrazoApp;use ingetrazo_core::{image_plane::ImagePlane,scene::SelectionItem,math::Ray};use ingetrazo_tools::base::{ToolContext,ToolType};fn main(){let mut a=IngeTrazoApp::new();a.system_clipboard=None;let im=ImagePlane::new("scan",V::ZERO,V::X*2.,V::Y*2.);let id=im.id;a.scene.image_planes.push(im);a.scene.image_objects.publish(&a.scene.image_planes);a.scene.select(SelectionItem::ImagePlane(0));a.set_tool(ToolType::Move);a.dispatch_tool_click(&ToolContext::new(V::ZERO,Ray::new(V::new(0.5,0.5,1.),-V::Z)));a.scene.image_planes.clear();a.scene.clear_selection();a.undo_stack.clear();a.redo_stack.clear();a.collect_image_metadata();let alive=a.scene.image_objects.0.lock().unwrap().contains_key(&id);a.active_tool.on_cancel(&mut a.scene);a.collect_image_metadata();let released=!a.scene.image_objects.0.lock().unwrap().contains_key(&id);println!("{}",serde_json::json!({"detached_tool_owner":alive,"released_after_cancel":released}));}
